{
  "$schema": "https://mintlify.com/docs.json",
  "name": "Superlog",
  "theme": "mint",
  "favicon": "https://media.brand.dev/b517a2c9-12a7-4caa-9afc-34d21e942292.jpg",
  "colors": {
    "primary": "#7c7c7c",
    "light": "#050505",
    "dark": "#d1d1d1"
  },
  "navbar": {
    "primary": {
      "type": "github",
      "href": "https://github.com/superloglabs/superlog"
    }
  },
  "navigation": {
    "tabs": [
      {
        "tab": "Documentation",
        "groups": [
          {
            "group": "Get Started",
            "pages": [
              "introduction",
              "quickstart",
              "self-hosting"
            ]
          },
          {
            "group": "Core Concepts",
            "pages": [
              "concepts/incidents",
              "concepts/agent-runs",
              "concepts/projects-and-orgs",
              "concepts/telemetry"
            ]
          },
          {
            "group": "Integrations",
            "pages": [
              "integrations/github",
              "integrations/slack",
              "integrations/linear",
              "integrations/aws"
            ]
          },
          {
            "group": "Features",
            "pages": [
              "features/dashboards",
              "features/alerts",
              "features/source-maps",
              "features/issue-filters",
              "features/agent-memory",
              "features/mcp"
            ]
          },
          {
            "group": "Configuration",
            "pages": [
              "configuration/ingest-keys",
              "configuration/agent-settings",
              "configuration/webhooks"
            ]
          }
        ]
      },
      {
        "tab": "API Reference",
        "groups": [
          {
            "group": "Management API",
            "pages": [
              "api/overview",
              "api/authentication",
              "api/projects",
              "api/api-keys",
              "api/telemetry-read"
            ]
          },
          {
            "group": "OTLP Ingest",
            "pages": [
              "api/otlp-ingest"
            ]
          },
          {
            "group": "MCP Server",
            "pages": [
              "api/mcp-overview",
              "api/mcp-tools"
            ]
          }
        ]
      }
    ]
  },
  "logo": {
    "light": "/images/NoBG-landscapedarktight.svg",
    "dark": "/images/NoBG-landscapelighttight.svg"
  },
  "appearance": {
    "default": "dark"
  }
}
